import json, math

with open('/root/autodl-tmp/vla-ssd/results/rsa/unified_rsa_results.json') as f:
    data = json.load(f)

# Fix summary: filter NaN
summary = {}
for cond, cond_res in data['conditions'].items():
    for agg, layer_res in cond_res.items():
        valid = {
            k: v['mean_rsa']
            for k, v in layer_res.items()
            if v['mean_rsa'] is not None and not (isinstance(v['mean_rsa'], float) and math.isnan(v['mean_rsa']))
        }
        if valid:
            best_k = max(valid, key=valid.get)
            best_l = int(best_k.split('_')[1])
            best_r = valid[best_k]
            summary[f'{cond}_{agg}_best'] = {'layer': best_l, 'rsa': best_r}

data['summary'] = summary

# Fix instruction_control
ic_mapping = {
    'normal': 'trained_with_inst',
    'no_inst': 'trained_no_inst',
    'random_s0': 'random_s0',
    'shuffled': 'shuffled',
}
instruction_control = {}
for ic_name, cond_name in ic_mapping.items():
    if cond_name in data['conditions'] and 'image_mean' in data['conditions'][cond_name]:
        layer_res = data['conditions'][cond_name]['image_mean']
        valid = {
            k: v['mean_rsa']
            for k, v in layer_res.items()
            if v['mean_rsa'] is not None and not (isinstance(v['mean_rsa'], float) and math.isnan(v['mean_rsa']))
        }
        if valid:
            best_k = max(valid, key=valid.get)
            best_l = int(best_k.split('_')[1])
            best_r = valid[best_k]
            instruction_control[ic_name] = {
                'best_layer': best_l,
                'best_rsa': best_r,
                'all_layers': {k: v['mean_rsa'] for k, v in layer_res.items()},
            }

data['instruction_control'] = instruction_control

with open('/root/autodl-tmp/vla-ssd/results/rsa/unified_rsa_results.json', 'w') as f:
    json.dump(data, f, indent=2)

print('Fixed summary:')
for k, v in summary.items():
    print(f'  {k}: layer {v[\"layer\"]}, RSA = {v[\"rsa\"]:.4f}')

print()
print('Instruction Control:')
for k, v in instruction_control.items():
    print(f'  {k}: best layer {v[\"best_layer\"]}, RSA = {v[\"best_rsa\"]:.4f}')
